const PFX=(()=>{const g={};AD.lmd_broadcast.own_host_prefixes_24.forEach(p=>{const a=p.split('.');const k=a[0]+'.'+a[1];(g[k]=g[k]||[]).push(+a[2]);});return Object.entries(g).map(([k,v])=>v.length>1?`${k}.{${v.sort((x,y)=>x-y).join(', ')}}.0/24`:`${k}.${v[0]}.0/24`).join(' and ');})();
const INK='0b0b0b', INK2='3f3f3f', ACC='1f4e79', HEADBG='1f4e79', ZEBRA='f2f5fb', FONT='Calibri';
const f3=(x)=>Number(x).toFixed(3), f4=(x)=>Number(x).toFixed(4), f2=(x)=>Number(x).toFixed(2);

// ---------- helpers ----------
const fixminus=(x)=>typeof x==='string'?x.replace(/(^|[\s(=])-(\d)/g,'$1\u2212$2'):x;
function t(text,o={}){return new TextRun({text:fixminus(text),font:FONT,size:o.size||20,bold:o.bold,italics:o.italics,color:o.color||INK});}
function p(runs,o={}){ if(typeof runs==='string') runs=[t(runs,o)];
  return new Paragraph({children:runs,spacing:{line:o.line||360,after:o.after==null?80:o.after,before:o.before||0},alignment:o.align,keepNext:o.keepNext});}
function h1(x,pb){return new Paragraph({heading:HeadingLevel.HEADING_1,spacing:{before:pb?0:300,after:90},keepNext:true,pageBreakBefore:!!pb,children:[new TextRun({text:x,font:FONT,size:29,bold:true,color:ACC})]});}
function h2(x){return new Paragraph({heading:HeadingLevel.HEADING_2,spacing:{before:140,after:60},children:[new TextRun({text:x,font:FONT,size:24,bold:true,color:INK})]});}
function h3(x){return new Paragraph({heading:HeadingLevel.HEADING_3,spacing:{before:120,after:60},children:[new TextRun({text:x,font:FONT,size:22,bold:true,color:INK2})]});}
function bullet(runs){return new Paragraph({numbering:{reference:'bl',level:0},spacing:{line:330,after:40},children:typeof runs==='string'?[t(runs)]:runs});}
const TS=9940/9360;   // table widths were laid out for a 6.5-inch column; scale to the 6.69-inch column
function cell(content,w,o={}){ w=Math.round(w*TS); const kids=Array.isArray(content)?content:[content];
  const paras=kids.map(c=> typeof c==='string'? new Paragraph({keepNext:o.keepNext,children:[new TextRun({text:fixminus(c),font:FONT,size:o.size||17,bold:o.bold,color:o.color||INK})],spacing:{line:235,after:15,before:15},alignment:o.align}):c);
  return new TableCell({width:{size:w,type:WidthType.DXA},shading:o.fill?{type:ShadingType.CLEAR,fill:o.fill,color:'auto'}:undefined,margins:{top:35,bottom:35,left:80,right:80},verticalAlign:'center',children:paras});}
function headerRow(labels,widths){return new TableRow({tableHeader:true,cantSplit:true,children:labels.map((l,i)=>cell(l,widths[i],{bold:true,color:'ffffff',fill:HEADBG,size:17}))});}
function table(widths,rows){widths=widths.map(w=>Math.round(w*TS));return new Table({columnWidths:widths,width:{size:widths.reduce((a,b)=>a+b,0),type:WidthType.DXA},
  borders:{top:{style:BorderStyle.SINGLE,size:2,color:'bfbfbf'},bottom:{style:BorderStyle.SINGLE,size:2,color:'bfbfbf'},left:{style:BorderStyle.SINGLE,size:2,color:'bfbfbf'},right:{style:BorderStyle.SINGLE,size:2,color:'bfbfbf'},insideHorizontal:{style:BorderStyle.SINGLE,size:2,color:'d9d9d9'},insideVertical:{style:BorderStyle.SINGLE,size:2,color:'d9d9d9'}},rows});}
function drow(cells,widths,i,o={}){const longest=Math.max(...cells.map(c=>String(c).length)); return new TableRow({cantSplit:longest<260,children:cells.map((c,j)=>cell(c,widths[j],{size:o.size||17,fill:(i%2===1)?ZEBRA:undefined,bold:o.boldCol0&&j===0,keepNext:false,align:((o.centerFrom!=null&&j>=o.centerFrom)&&!(o.leftCols||[]).includes(j))?AlignmentType.CENTER:undefined}))});}
function tcap(n,x){const para=new Paragraph({keepNext:true,keepLines:true,spacing:{before:120,after:50},children:[new TextRun({text:`Table ${n}. `,font:FONT,size:17,bold:true,color:INK2}),new TextRun({text:fixminus(x),font:FONT,size:17,italics:true,color:INK2})]}); para.__tcap=true; return para;}
function figure(name,n,cap,targetW){const [w,h]=dims[name];const W=Math.min(targetW||624,624);const H=Math.round(h*W/w);
  return [new Paragraph({keepNext:true,alignment:AlignmentType.CENTER,spacing:{before:80,after:30},children:[new ImageRun({type:'png',data:fs.readFileSync(`${FIG}/${name}`),transformation:{width:W,height:H}})]}),
          new Paragraph({alignment:AlignmentType.CENTER,spacing:{after:140},children:[new TextRun({text:`Figure ${n}. `,font:FONT,size:17,bold:true,color:INK2}),new TextRun({text:cap,font:FONT,size:17,italics:true,color:INK2})]})];}
const C=[];
const S=RT.summary, SP=RT.split, ML=RT.meta.LMD, MM=RT.meta.Mordor;

// ===================== TITLE PAGE =====================
