['Ela Ambar Grynbaum — ela.ambar2306@gmail.com','Daniel Shostak — danshostak0@gmail.com','Itamar Tsafrir Ornstein — itamarit77@gmail.com','Itamar Klartag — itamarklartag@gmail.com']
 .forEach(m=>C.push(new Paragraph({alignment:AlignmentType.CENTER,spacing:{after:30},children:[t(m,{size:20})]})));
